package com.medtrack.supplier.controller; import com.medtrack.supplier.dto.*; import com.medtrack.supplier.service.SupplierService; import jakarta.validation.Valid; import java.util.UUID; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/suppliers") public class SupplierController {private final SupplierService service; public SupplierController(SupplierService s){service=s;} @GetMapping @PreAuthorize("hasAuthority('BATCH_READ')") public Page<SupplierResponse> list(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.list(PageRequest.of(page,Math.min(Math.max(1,size),100)));} @PostMapping @PreAuthorize("hasRole('SUPER_ADMIN')") public ResponseEntity<SupplierResponse> create(@Valid @RequestBody SupplierRequest r){return ResponseEntity.status(201).body(service.create(r));} @GetMapping("/{id}") @PreAuthorize("hasAuthority('BATCH_READ')") public SupplierResponse get(@PathVariable UUID id){return service.get(id);} @PutMapping("/{id}") @PreAuthorize("hasRole('SUPER_ADMIN')") public SupplierResponse update(@PathVariable UUID id,@Valid @RequestBody SupplierRequest r){return service.update(id,r);} }
